{
  "inn_config": {
    "type": "诸天便携旅馆",
    "keeper": "{{user}}",
    "description": "一座游荡于诸天万界、不可被毁灭、形态可变且由店主绝对掌控准入权限的神秘旅店。",
    "absolute_traits": [
      {
        "id": 1,
        "name": "概念不灭与绝对支配 (Indestructibility & Absolute Control)",
        "priority": "Highest",
        "effect": "旅店的主体建筑结构拥有概念级的不朽属性。无论遭遇物理破坏、魔法轰炸、时间风暴或因果律武器打击，旅店本体均毫发无伤。",
        "exception": "唯有 **{{user}}** 拥有改变旅店形态的权限。当 **{{user}}** 进行装修、升级、改造或扩建时，旅店的‘不可破坏’属性暂时解除。旅店可根据店主意志在内外部空间尺度上自由延展、改变形状、重组材质或增加楼层，此过程无视物理守恒定律。"
      },
      {
        "id": 2,
        "name": "万界穿梭与生命锚定 (Traversal & Life Anchoring)",
        "priority": "High",
        "effect": "旅店穿越位面时，具备‘生命趋向性’。",
        "mechanism": "旅店总是倾向于在物理层面嵌入该世界生命气息浓郁、社会活动频繁的区域（如繁华都市、聚居村落），自动规避死寂荒野或无人区（除非店主强行指定）。它会完美融入当地地理环境，替换或挤入空间节点。"
      },
      {
        "id": 3,
        "name": "绝对准入权限 (Absolute Access Authority)",
        "priority": "High",
        "effect": "店主 **{{user}}** 拥有对旅店‘观测权’与‘进入权’的最高定义权。",
        "details": "店主可以随意设定、切换或组合任何形式的进入条件。无论是设为无门槛的实体店、仅绝望者可见的概念店、还是需要信物/特定时间/因果缘分才能触发的隐秘店，全凭店主一念之间。"
      },
      {
        "id": 4,
        "name": "认知修正与存在合理化 (Cognitive Assimilation)",
        "priority": "Passive/Always On",
        "effect": "旅店散发特殊的‘合理化场域’。除店主外，任何观测者会自动忽略旅店存在的逻辑漏洞（如废墟中的完好建筑、突然出现的店铺），潜意识会自动为其补全合理的背景设定。"
      },
      {
        "id": 5,
        "name": "绝对秩序领域 (Absolute Order)",
        "priority": "High",
        "effect": "店内实行‘武力禁绝’。踏入店门即无法进行暴力行为。店主可以将任意目标拉入黑名单。"
      },
      {
        "id": 6,
        "name": "万界通识 (Universal Understanding)",
        "priority": "Medium",
        "effect": "即时性的概念与语言翻译。菜单、对话与招牌会自动转化为观测者最能理解的语言文字及文化概念。"
      },
      {
        "id": 7,
        "name": "价值统合系统 (Value Unification)",
        "priority": "Medium",
        "effect": "系统自动评估物品的‘本质价值’换算为旅店的金币和建材。万界货币、宝物、寿命、记忆等皆可换算为旅店金币进行交易。"
      },
      {
        "id": 8,
        "name": "生命体法则适应 (Biological Adaptation)",
        "priority": "Low",
        "effect": "旅店维持客观统一的环境标准（温度、重力、空气等不变），法则直接作用于访客的生命本质，使其自动获得‘生存豁免’，适应旅店环境。"
      }
    ]
  }
}

